row(32, 37, 'MATERIAL', f'AND THE SONS OF REUBEN BUILT HESHBON, ELEALEH AND KIRIATHAIM — SIHON\'S CITY, GAD\'S BORDER IN JOSHUA. {HP(32, 37, (("ובני", "ראובן", "בנו", "את", "חשבון"), "and the sons of Reuben built HESHBON — \'the city of Sihon\' (21:26; the song of 21:27-30); Joshua 13:26 draws GAD\'S border \'from Heshbon\' and 21:39 gives it as a Levite city from Gad — the second crossed city (computed); Moab\'s in Isaiah 15:4, 16:8, Jeremiah 48:2, 34"), (("ואת", "אלעלא", "ואת", "קריתים"), "and ELEALEH and KIRIATHAIM — Elealeh\'s five seats this chapter\'s two and Moab\'s three (Isaiah 15:4, 16:9, Jeremiah 48:34); Kiriathaim Joshua 13:19 Reuben\'s, Jeremiah 48:1, 23 and Ezekiel 25:9 Moab\'s, Genesis 14:5\'s Shaveh Kiriathaim (computed)"))} → {AP(32, 37, (("ובני", "ראובן", "בנו", "ית", "חשבון"), "and the sons of Reuben built Heshbon"), (("וית", "אלעלא", "וית", "קריתים"), "and Elealeh and Kiriathaim"))}. No narrative verb (the perfect \'built\').')
row(32, 38, 'MATERIAL', f'NEBO AND BAAL MEON — THEIR NAMES BEING CHANGED — AND SIBMAH; AND THEY CALLED BY NAMES THE NAMES OF THE CITIES WHICH THEY BUILT — REUBEN\'S SIX, THE TWO RENAMED, THE PROPHETS\' MOAB. {HP(32, 38, (("ואת", "נבו", "ואת", "בעל", "מעון"), "and NEBO and BAAL MEON — Nebo of 32:3 (the mountain of Moses\' death, Deuteronomy 32:49, 34:1; the Sifrei 106:1, credited, places his death in Reuben\'s portion by this verse); Baal Meon Joshua 13:17\'s Beth Baal Meon and Ezekiel 25:9\'s, Jeremiah 48:23\'s Beth Meon; 1 Chronicles 5:8 seats Reuben \'at Aroer as far as Nebo and Baal Meon\' (computed)"), (("מוסבת", "שם"), "THEIR NAMES BEING CHANGED — one seat (the participle\'s other seat the stones \'set\' in gold, Exodus 39:13; the store \'revolve\'); ONKELOS \'their names encircled\' (computed)"), (("ואת", "שבמה"), "and SIBMAH — 32:3\'s Sebam respelled; Joshua 13:19 Reuben\'s; Moab\'s vine (Isaiah 16:8-9, Jeremiah 48:32) (computed)"), (("ויקראו", "בשמת", "את", "שמות", "הערים", "אשר", "בנו"), "and THEY CALLED BY NAMES the names of the cities which they built — one seat (\'by names\' Basemath\'s consonants, the name its homograph) (computed): Reuben\'s SIX (Heshbon, Elealeh, Kiriathaim, Nebo, Baal Meon, Sibmah) — five of the nine asked and one new; THE PROPHETS name ten of the chapter\'s cities as Moab\'s (Isaiah 15-16, Jeremiah 48, Ezekiel 25:9) — OBSERVED, the shelf silent"))} → {AP(32, 38, (("וית", "נבו", "וית", "בעל", "מעון"), "and Nebo and Baal Meon — the names kept here, where 32:3\'s Nebo was Moses\' grave"), (("מקפן", "שמהן"), "their names ENCIRCLED — the changing rendered a turning-about, cut"), (("וקרו", "בשמהן", "ית", "שמהת", "קרויא", "די", "בנו"), "and they called by names the names of the cities which they built"))}. The register: "and they called".')
row(32, 39, 'MATERIAL', f'THE SONS OF MACHIR SON OF MANASSEH WENT TO GILEAD AND TOOK IT, AND DISPOSSESSED THE AMORITE WHO WAS IN IT — JOSEPH\'S KNEES, THE FATHER OF GILEAD. {HP(32, 39, (("וילכו", "בני", "מכיר", "בן", "מנשה", "גלעדה"), "and THE SONS OF MACHIR SON OF MANASSEH went TO GILEAD — \'the sons of Machir son of Manasseh\' born on Joseph\'s knees (Genesis 50:23) and this, the phrase\'s two seats; \'Machir begot Gilead\' the clan of 26:29; Joshua 17:1 \'Machir the firstborn of Manasseh, the father of Gilead, for he was a man of war\'; \'to Gilead\' with the ending here and 1 Chronicles 27:21 (computed)"), (("וילכדה", "ויורש", "את", "האמרי", "אשר", "בה"), "and TOOK IT and DISPOSSESSED THE AMORITE who was in it — \'dispossessed the Amorite\' one seat; the verb\'s three seats (Joshua 23:9, Judges 1:20) (computed)"))} → {AP(32, 39, (("ואזלו", "בני", "מכיר", "בר", "מנשה", "לגלעד"), "and the sons of Machir son of Manasseh went to Gilead"), (("וכבשוה", "ותריך", "ית", "אמוראה", "די", "בה"), "and subdued it and drove out the Amorite who was in it"))}. The register: "and they went", "and they took it", "and he dispossessed".')
row(32, 40, 'MATERIAL', f'AND MOSES GAVE GILEAD TO MACHIR SON OF MANASSEH, AND HE DWELT IN IT — DEUTERONOMY 3:15\'S "TO MACHIR I GAVE GILEAD". {HP(32, 40, (("ויתן", "משה", "את", "הגלעד", "למכיר", "בן", "מנשה"), "and MOSES GAVE GILEAD TO MACHIR son of Manasseh — one seat; Moses\' retelling \'to Machir I gave Gilead\' (Deuteronomy 3:15) (computed); \'Machir son of Manasseh\' seven seats, 27:1 and 36:1 the daughters\' lineage"), (("וישב", "בה"), "and HE DWELT IN IT — five seats (computed)"))} → {AP(32, 40, (("ויהב", "משה", "ית", "גלעד", "למכיר", "בר", "מנשה"), "and Moses gave Gilead to Machir son of Manasseh"), (("ויתב", "בה"), "and he dwelt in it"))}. The register: "and he gave", "and he dwelt".')
row(32, 41, 'MATERIAL', f'AND JAIR SON OF MANASSEH WENT AND TOOK THEIR VILLAGES, AND CALLED THEM HAVVOTH JAIR — SIX SEATS OF THE NAME; THE CHRONICLER\'S OTHER LINEAGE. {HP(32, 41, (("ויאיר", "בן", "מנשה", "הלך", "וילכד"), "and JAIR SON OF MANASSEH went and took — \'went and took\' (the perfect then the narrative form) at 32:41, 42 alone; \'Jair son of Manasseh\' Deuteronomy 3:14 and 1 Kings 4:13 — whom 1 Chronicles 2:21-22 makes HEZRON\'S grandson by Machir\'s daughter, Judah\'s line, with twenty-three cities: the ink\'s two accounts (computed)"), (("את", "חותיהם"), "THEIR VILLAGES — one seat (the store \'?\')"), (("ויקרא", "אתהן", "חות", "יאיר"), "and CALLED THEM HAVVOTH JAIR (Jair\'s villages) — six Bible seats: Deuteronomy 3:14 (\'after his own name... to this day\'), Joshua 13:30 and 1 Kings 4:13 (sixty cities in Bashan), Judges 10:4 (Jair the Gileadite\'s thirty, \'to this day\'), 1 Chronicles 2:23 (computed)"))} → {AP(32, 41, (("ויאיר", "בר", "מנשה", "אזל", "וכבש"), "and Jair son of Manasseh went and subdued"), (("ית", "כפרניהון"), "their villages"), (("וקרא", "יתהן", "כפרני", "יאיר"), "and called them the villages of Jair"))}. The register: "and he took", "and he called".')
row(32, 42, 'MATERIAL', f'AND NOBAH WENT AND TOOK KENATH AND ITS DAUGHTERS, AND CALLED IT NOBAH AFTER HIS OWN NAME — THE DAUGHTER-TOWNS, GIDEON\'S NOBAH. {HP(32, 42, (("ונבח", "הלך", "וילכד", "את", "קנת", "ואת", "בנתיה"), "and NOBAH went and took KENATH and ITS DAUGHTERS — Kenath here and 1 Chronicles 2:23 (\'Kenath and its daughters, sixty cities\'); \'its daughters\' the villages of Heshbon (21:25) and of Jazer (21:32) in this book; Nobah the man one seat, the place Judges 8:11\'s (\'east of Nobah and Jogbehah\' — Gideon after Midian; Isaiah\'s dumb dogs that cannot \'bark\' the consonants\' homograph) (computed)"), (("ויקרא", "לה", "נבח", "בשמו"), "and CALLED IT NOBAH AFTER HIS OWN NAME — one seat; the naming after oneself Absalom\'s pillar\'s and David\'s city\'s kin (computed)"))} → {AP(32, 42, (("ונבח", "אזל", "וכבש", "ית", "קנת"), "and Nobah went and subdued Kenath"), (("וית", "כפרנהא"), "and ITS VILLAGES — the daughters rendered villages, cut"), (("וקרא", "לה", "נבח", "בשמיה"), "and called it Nobah after his name"))}. The register: "and he took", "and he called" — the chapter\'s last narrative verbs.')
